def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    S = 8
    mask8 = (g == S)
    comps = components(mask8, diagonal=True)
    comp_id = {}
    for i, c in enumerate(comps):
        for p in c:
            comp_id[p] = i

    # find legends: source s, adjacent target t, then anchor touching an 8-shape
    legends = []  # (source, target, stencil offsets, legend cells)
    for y in range(H):
        for x in range(W):
            s = g[y, x]
            if s == bg or s == S:
                continue
            for dy, dx in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                ty, tx = y + dy, x + dx
                if not (0 <= ty < H and 0 <= tx < W):
                    continue
                t = g[ty, tx]
                if t == bg or t == S or t == s:
                    continue
                ay, ax = ty + dy, tx + dx
                if not (0 <= ay < H and 0 <= ax < W):
                    continue
                ids = set()
                for ny in range(ay - 1, ay + 2):
                    for nx in range(ax - 1, ax + 2):
                        if (ny, nx) in comp_id:
                            ids.add(comp_id[(ny, nx)])
                if not ids:
                    continue
                cells = [p for i in ids for p in comps[i]]
                offs = [(p[0] - ay, p[1] - ax) for p in cells]
                legends.append((int(s), int(t), offs, [(y, x), (ty, tx)] + cells))

    legend_cells = set()
    for _, _, _, cells in legends:
        legend_cells.update(cells)
    mapping = {}
    for s, t, offs, _ in legends:
        mapping[s] = (t, offs)

    out = g.copy()
    for y, x in legend_cells:
        out[y, x] = bg
    for colour in mapping:
        out[g == colour] = bg
    emit(out.copy(), "Erase the legends (source, target and 8-stencil) and every cell of a mapped source colour; unmapped colours stay.")

    for s, (t, offs) in mapping.items():
        for y in range(H):
            for x in range(W):
                if g[y, x] == s and (y, x) not in legend_cells:
                    for oy, ox in offs:
                        ny, nx = y + oy, x + ox
                        if 0 <= ny < H and 0 <= nx < W:
                            out[ny, nx] = t
        emit(out.copy(), f"Replace every loose colour-{s} cell by the legend's 8-stencil drawn in colour {t}.")

    emit(out.copy(), "Final grid.")
    return out
